class Solution {
public:
    int countTexts(string pressedKeys) {
        const long long MOD = 1000000007;
        int n = pressedKeys.size();
        long long result = 1;

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && pressedKeys[j] == pressedKeys[i]) j++;
            int len = j - i;
            char d = pressedKeys[i];
            int maxGroup = (d == '7' || d == '9') ? 4 : 3;

            long long dp[5] = {0, 0, 0, 0, 0};
            dp[0] = 1;
            for (int k = 1; k <= len; k++) {
                long long val = dp[(k - 1) % 5];
                if (k >= 2) val += dp[(k - 2) % 5];
                if (k >= 3) val += dp[(k - 3) % 5];
                if (k >= 4 && maxGroup == 4) val += dp[(k - 4) % 5];
                dp[k % 5] = val % MOD;
            }

            result = (result * dp[len % 5]) % MOD;
            i = j;
        }

        return (int)result;
    }
};
